# GDB Python: hardware observations only; no inferior function calls or writes.
import gdb, json, os, time
meta = json.load(open(os.environ['DIAG_META']))
out = open(os.environ['DIAG_EVENTS'], 'w', buffering=1)
start = time.monotonic()
ticks = {}
retained = []
entry_events = 0

def u64(addr):
    return int.from_bytes(gdb.selected_inferior().read_memory(addr, 8).tobytes(), 'little')

def ruby_string(value):
    if int(value) < 4096:
        return None
    s = gdb.Value(value).cast(gdb.lookup_type('struct RString').pointer()).dereference()
    n = int(s['len'])
    if n < 0 or n > 4096:
        return '<unavailable-string>'
    addr = int(s['as']['heap']['ptr']) if int(s['basic']['flags']) & 0x2000 else int(s['as']['embed']['ary'].address)
    return gdb.selected_inferior().read_memory(addr, n).tobytes().decode('utf-8', 'replace')

def context():
    ec = gdb.parse_and_eval('ruby_current_ec')
    if not int(ec):
        return {'unavailable': 'no ec'}
    thread = ec['thread_ptr']
    name = ruby_string(thread['name'])
    frame = ec['cfp']
    end = int(ec['vm_stack'] + ec['vm_stack_size'])
    frames = []
    while int(frame) + int(frame.dereference().type.sizeof) <= end and len(frames) < 40:
        iseq = frame['iseq']
        if int(iseq) and int(iseq['body']):
            body = iseq['body']
            loc = body['location']
            path = loc['pathobj']
            # pathobj is String or [path, realpath]. Only labels are required.
            frames.append({'label': ruby_string(loc['label']), 'first_lineno': int(loc['first_lineno']),
                           'pc_index': int(frame['pc'] - body['iseq_encoded']) if int(frame['pc']) else None,
                           'iseq': int(iseq)})
        frame += 1
    return {'ruby_thread': int(thread), 'name': name, 'frames': frames}

def emit(kind, extra=None):
    try:
        ctx = context()
    except Exception as e:
        ctx = {'unavailable': str(e)}
    tid = str(ctx.get('ruby_thread'))
    row = {'event': kind, 'elapsed_s': time.monotonic()-start,
           'lwp': gdb.selected_thread().ptid[1], 'request': u64(meta['progress']),
           'phase': u64(meta['progress']+8), 'calls': u64(meta['body']+312),
           'entry': u64(meta['body']+304), 'tick': ticks.get(tid, 1), **ctx, **(extra or {})}
    out.write(json.dumps(row)+'\n')
    return row

class Entry(gdb.Breakpoint):
    def stop(self):
        global entry_events
        entry_events += 1
        emit('normal_jit_entry')
        if entry_events >= 300:
            emit('entry_event_cap_incomplete')
            self.enabled = False
        return False

class Watch(gdb.Breakpoint):
    def __init__(self, offset, kind):
        self.kind = kind
        super().__init__('*(unsigned long*)%d' % (meta['body']+offset), type=gdb.BP_WATCHPOINT,
                         wp_class=gdb.WP_WRITE, internal=True)
    def stop(self):
        row = emit(self.kind)
        if self.kind == 'installation' and row['entry']:
            retained.append(Entry('*0x%x' % row['entry'], type=gdb.BP_HARDWARE_BREAKPOINT, internal=True))
        return False

class Sleep(gdb.Breakpoint):
    def stop(self):
        try:
            ctx = context()
            if ctx.get('name') == 'AR Pool Reaper':
                tid = str(ctx['ruby_thread'])
                emit('reaper_sleep')
                ticks[tid] = ticks.get(tid, 1)+1
        except Exception as e:
            emit('sleep_read_error', {'error':str(e)})
        return False

retained.append(Watch(312, 'normal_entry_counter'))
retained.append(Watch(304, 'installation'))
retained.append(Sleep('rb_f_sleep', type=gdb.BP_HARDWARE_BREAKPOINT, internal=True))
emit('ready', {'initial': meta['initial']})
gdb.execute('info breakpoints')
gdb.execute('continue')
out.close()
